import { createHash, randomInt } from 'node:crypto';

import type { Db } from '../db/client.ts';

// Activation codes like K7P-42Q: generated by the admin, stored only as a SHA-256 hash,
// single use, valid for 7 days.

// No 0/O, 1/I/L, so a code read off a phone can't be mistyped between look-alikes.
const ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
const DIGITS = '23456789';
const LETTERS = 'ABCDEFGHJKMNPQRSTUVWXYZ';
export const CODE_TTL_DAYS = 7;

// Six characters with at least one digit and one letter, shown as XXX-XXX.
export function generateCode(): string {
  for (;;) {
    const chars = Array.from({ length: 6 }, () => ALPHABET.charAt(randomInt(ALPHABET.length)));
    if (chars.some((c) => DIGITS.includes(c)) && chars.some((c) => LETTERS.includes(c))) {
      return `${chars.slice(0, 3).join('')}-${chars.slice(3).join('')}`;
    }
  }
}

// The code in a message ("@Ent k7p-42q", "K7P42Q"), normalised to XXX-XXX, or null. Only a
// dashed code or a six-character word with a digit counts, so ordinary words like "please"
// aren't taken for wrong codes.
export function extractCode(text: string): string | null {
  for (const token of text.toUpperCase().split(/\s+/)) {
    const word = token.replace(/^[^A-Z0-9]+|[^A-Z0-9]+$/g, '');
    const dashed = /^([A-Z0-9]{3})-([A-Z0-9]{3})$/.exec(word);
    if (dashed !== null) return `${dashed[1] ?? ''}-${dashed[2] ?? ''}`;
    if (/^[A-Z0-9]{6}$/.test(word) && /[0-9]/.test(word) && /[A-Z]/.test(word)) {
      return `${word.slice(0, 3)}-${word.slice(3)}`;
    }
  }
  return null;
}

export function hashCode(code: string): string {
  return createHash('sha256').update(code).digest('hex');
}

// Stores a new code and returns it in plain text: the only time it can be seen.
export async function createCode(
  db: Db,
  createdBy: string | null,
  now: Date = new Date(),
): Promise<{ code: string; expiresAt: Date }> {
  const code = generateCode();
  const expiresAt = new Date(now.getTime() + CODE_TTL_DAYS * 24 * 60 * 60 * 1000);
  await db
    .insertInto('activation_codes')
    .values({ code_hash: hashCode(code), created_by: createdBy, expires_at: expiresAt })
    .execute();
  return { code, expiresAt };
}

export type RedeemResult =
  { ok: true } | { ok: false; reason: 'unknown' | 'used' | 'expired' | 'not_pending' };

// Uses a code to activate a pending household. The caller tells the chat only "activated" or
// "that code didn't work"; `reason` is for the logs.
export async function redeemCode(
  db: Db,
  householdId: string,
  code: string,
  now: Date = new Date(),
): Promise<RedeemResult> {
  return db.transaction().execute(async (trx): Promise<RedeemResult> => {
    const row = await trx
      .selectFrom('activation_codes')
      .selectAll()
      .where('code_hash', '=', hashCode(code))
      .forUpdate()
      .executeTakeFirst();
    if (row === undefined) return { ok: false, reason: 'unknown' };
    if (row.used_at !== null) return { ok: false, reason: 'used' };
    if (row.expires_at <= now) return { ok: false, reason: 'expired' };

    const activated = await trx
      .updateTable('households')
      .set({ status: 'active', activated_at: now })
      .where('id', '=', householdId)
      .where('status', '=', 'pending')
      .returning('id')
      .executeTakeFirst();
    if (activated === undefined) return { ok: false, reason: 'not_pending' };

    await trx
      .updateTable('activation_codes')
      .set({ used_at: now, household_id: householdId })
      .where('code_hash', '=', row.code_hash)
      .execute();
    return { ok: true };
  });
}
